# Module-level constants
  @const chanMsgEvTypes = { [0xA0] = 'pa', [0xB0] = 'cc', [0xC0] = 'pc', [0xD0] = '...  @ 20
  @const shapeNames = { [0] = 'step', [1] = 'linear', [2] = 'slow',  @ 21
  @const shapeCodes, hiByEvType = {}, {}  @ 24
  @const oneDataByte = { pc = true, at = true }  @ 27   -- status + a single 7-bit data byte
  @const midiBlob = {}  @ 39
  @const chunkCache = setmetatable({}, { __mode = 'k' })  @ 155
  @const RANK_STRIDE = 100000000  @ 200   -- the band seq2 lives under, so a slot stays below 5e7
  @const PPQ_STRIDE = 1000000000  @ 201   -- rank's single digit sits between the two

# Private functions
  @fn isWideCC(c)  @ 31
      -- 14-bit CC: a code in 0..31 with a fractional value rides an LSB on code+32.
      -- The value's type is the whole signal -- an integer value stays a plain 7-bit CC.
  @fn splitWide(val)  @ 32-37
  @fn ccValueFields(evType, b2, b3)  @ 42-47
      -- The value-bearing fields for a cc-family event, keyed as mm:load stores them.
  @fn ccDataBytes(c)  @ 126-131
      -- Value bytes for a cc-family record (inverse of ccValueFields).
  @fn ccWire(c)  @ 133-138
  @fn noteRow(n)  @ 157-165
  @fn ccRow(c)  @ 167-177
  @fn textRow(x)  @ 179-186
  @fn textChunk(x, dppq)  @ 188-196
  @fn packKey(ppq, rank, seq2)  @ 203
  @fn chunkOf(kv, dppq, notes, ccs, texts, passthrough)  @ 207-260
      -- Decodes a packed sort key to its wire chunk(s): rank digit picks the stream, seq//2
      -- the event's slot, an odd seq a cc's bezier CCBZ rider. Mirrors midiBlob.parse.
  @fn lowerBound(keys, kv)  @ 320-327
      -- First index whose key is >= kv, over the ascending key array.
  @fn chunkAt(wire, i)  @ 331-337
      -- Re-derives the predecessor's ppq rather than carrying it forward: a splice has no
      -- walk to carry it from, which is why buildWire keeps its own loop.
  @fn keysOfSlot(stream, slot, st)  @ 369-382
      -- The keys one slot contributes, off a before-snapshot or off the live model alike --
      -- deriving both sides of a sync through one helper is what keeps them honest.
  @fn holds(keys, kv)  @ 384-387

# Public API (midiBlob.*)
  @api midiBlob.parse(blob)  @ 49-123
  @api midiBlob.buildWire(notes, ccs, texts, passthrough)  @ 264-317
      -- Keys, sorts and packs the model into wire state the caller holds across flushes,
      -- so an edit can replace the chunks it touched instead of rebuilding all of them.
  @api midiBlob.putKey(wire, kv)  @ 341-348
      -- A chunk's delta comes from its predecessor's ppq, so a splice moves only its
      -- own delta and its successor's. See docs/midiBlob.md § Splicing a held wire.
  @api midiBlob.dropKey(wire, kv)  @ 350-357
  @api midiBlob.repackKey(wire, kv)  @ 360-365
      -- The property edit: the key does not move, only the bytes under it.
  @api midiBlob.slotState(wire, stream, slot)  @ 391-398
      -- The sidecar key comes off the row's own ppq, not its owner's: the row is what chunkOf
      -- packs, so a stale row surfaces as a wrong key instead of being papered over.
  @api midiBlob.syncSlots(wire, dirt)  @ 402-423
      -- Carry every dirty slot's keys from the caller's before-snapshots to what the model now
      -- says, phased so chunkOf never packs a dead key -- see docs/midiBlob.md § Splicing a held wire.
  @api midiBlob.render(wire, endPpq)  @ 427-438
      -- The tail goes on as a transient last element and comes straight back off:
      -- table.concat(chunks) .. tail would copy the whole blob to add twelve bytes.

